// Handles the ball bouncing off bricks (per-face), pushing the ball back out,
// applying the bounce exactly ONCE when the ball overlaps several bricks at a
// seam, and sweeping the path so a fast ball cannot tunnel through a brick.
// Advances the ball position and velocity in place. Returns the number of
// bricks destroyed (0 if none).
export function brickHit(ball, bricks, prev) {
  const startX = prev ? prev.x : ball.x;
  const startY = prev ? prev.y : ball.y;
  const dx = ball.x - startX;
  const dy = ball.y - startY;
  const dist = Math.hypot(dx, dy);

  // Substep so a fast ball cannot jump over a brick (tunnelling).
  const stepCount = Math.max(1, Math.ceil(dist / (ball.r * 0.5)));
  let totalDestroyed = 0;

  for (let i = 1; i <= stepCount; i++) {
    const t = i / stepCount;
    const probeX = startX + dx * t;
    const probeY = startY + dy * t;

    const hitBricks = bricks.filter(
      (b) => b.alive && circleRect(probeX, probeY, ball.r, b)
    );
    if (hitBricks.length === 0) continue;

    // Determine the dominant face(s) across all bricks hit in this substep.
    const face = dominantFace(probeX, probeY, ball.r, hitBricks);
    if (face === 'horizontal') {
      ball.vy = -ball.vy;
    } else if (face === 'vertical') {
      ball.vx = -ball.vx;
    } else {
      // corner
      ball.vx = -ball.vx;
      ball.vy = -ball.vy;
    }

    // Push the ball out along the resolved axis so it can't re-flip (sticky).
    pushOut(ball, hitBricks, face);

    for (const b of hitBricks) {
      b.alive = false;
      totalDestroyed += 1;
    }

    // Only the first contact matters for physics; stop.
    break;
  }

  return totalDestroyed;
}
