```js
// --- Brick collision resolution (pure, testable) ---------------------------

// Circle-vs-rect overlap for the ball against a single brick.
function circleRect(cx, cy, r, brick) {
  return (
    cx + r > brick.x &&
    cx - r < brick.x + brick.w &&
    cy + r > brick.y &&
    cy - r < brick.y + brick.h
  );
}

// Which face(s) of the overlapping bricks the ball hit. As the ball grazes a
// seam it overlaps several bricks at once; we look at the *aggregate* of all
// overlapping bricks so the bounce that follows is a single, coherent one.
// Returns 'side'  -> flip vx (ball struck a vertical face),
//         'topbottom' -> flip vy (ball struck a horizontal face),
//         'corner' -> overlapping penetrations -> flip both.
function hitFace(cx, cy, r, bricks) {
  let dLeft = Infinity, dRight = Infinity;
  let dTop = Infinity, dBottom = Infinity;
  for (const brick of bricks) {
    dLeft = Math.min(dLeft, cx + r - brick.x);
    dRight = Math.min(dRight, brick.x + brick.w - (cx - r));
    dTop = Math.min(dTop, cy + r - brick.y);
    dBottom = Math.min(dBottom, brick.y + brick.h - (cy - r));
  }
  const horizontal = Math.min(dLeft, dRight); // penetration into a side
  const vertical = Math.min(dTop, dBottom);   // penetration into top/bottom

  if (horizontal * 1.25 < vertical) return 'side';
  if (vertical * 1.25 < horizontal) return 'topbottom';
  return 'corner';
}

// Pushes the ball back out of the bricks it just hit, along the faces that
// were resolved, so it cannot keep overlapping on the next frame (sticky
// bounce). The direction follows the (already flipped) velocity, moving the
// ball away from the bricks.
function pushOut(ball, bricks, face) {
  let minLeft = Infinity, maxRight = -Infinity;
  let minTop = Infinity, maxBottom = -Infinity;
  for (const brick of bricks) {
    minLeft = Math.min(minLeft, brick.x);
    maxRight = Math.max(maxRight, brick.x + brick.w);
    minTop = Math.min(minTop, brick.y);
    maxBottom = Math.max(maxBottom, brick.y + brick.h);
  }
  if (face === 'topbottom' || face === 'corner') {
    ball.y = ball.vy >= 0 ? maxBottom + ball.r : minTop - ball.r;
  }
  if (face === 'side' || face === 'corner') {
    ball.x = ball.vx >= 0 ? maxRight + ball.r : minLeft - ball.r;
  }
}

// Resolves the ball against the bricks for one frame (the fix for #1).
//
//   - per face: the axis with the smaller penetration flips; the other
//     component is left exactly as it was;
//   - corner:   equal penetrations flip both components;
//   - push out: the ball is repositioned outside the bricks so it cannot
//     re-flip on the next frame (no sticky bounce);
//   - seam:     `vy = -vy` is never applied twice in the same pass, so the
//     ball cannot slip between two bricks;
//   - tunnelling: the path from `prev` to the ball's current position is
//     swept in substeps, so a fast ball cannot jump over a brick.
//
// Mutates `ball` and the `bricks` (destroying everything it hits). Returns
// the array of bricks destroyed (possibly empty).
export function brickHit(ball, bricks, prev) {
  const startX = prev ? prev.x : ball.prevX ?? ball.x;
  const startY = prev ? prev.y : ball.prevY ?? ball.y;
  const dx = ball.x - startX;
  const dy = ball.y - startY;
  const dist = Math.hypot(dx, dy);

  const substeps = Math.max(1, Math.ceil(dist / (ball.r * 0.5)));
  for (let i = 1; i <= substeps; i++) {
    const t = i / substeps;
    const probeX = startX + dx * t;
    const probeY = startY + dy * t;

    const hit = bricks.filter(
      (brick) => brick.alive && circleRect(probeX, probeY, ball.r, brick)
    );
    if (hit.length === 0) continue;

    ball.x = probeX;
    ball.y = probeY;
    const face = hitFace(probeX, probeY, ball.r, hit);
    if (face === 'side') {
      ball.vx = -ball.vx;
    } else if (face === 'topbottom') {
      ball.vy = -ball.vy;
    } else {
      ball.vx = -ball.vx;
      ball.vy = -ball.vy;
    }

    pushOut(ball, hit, face);

    for (const brick of hit) brick.alive = false;

    // Only the first contact is resolved this frame; the ball has bounced.
    return hit;
  }
  return [];
}
```

