export function step(state, dt) {
  const { ball, paddle } = state;

  // Remember where the ball was before this step so the brick bounce can
  // tell which face it struck (and to sweep for tunnelling).
  ball.prevX = ball.x;
  ball.prevY = ball.y;

  ball.x += ball.vx * dt;
  ball.y += ball.vy * dt;

