  assert.equal(brick.alive, false, 'brick is destroyed');
});

// Per face: hitting a side face flips vx, leaves vy alone.
test('brickHit: side-face hit flips vx only (vy untouched)', () => {
  const brick = brickFixture();
  const ball = { x: 345, y: 110, r: 7, vx: -300, vy: 0, prevX: 400, prevY: 110 };
  const destroyed = brickHit(ball, [brick]);
  assert.equal(destroyed.length, 1);
  assert.ok(ball.vx > 0, 'vx should flip to the right');
  assert.equal(ball.vy, 0, 'vy must be left exactly as it was');
});

// Corner: a diagonal entry flips both components.
test('brickHit: corner hit flips both vx and vy', () => {
  const brick = brickFixture();
  const ball = { x: 296, y: 97, r: 7, vx: 300, vy: 300, prevX: 290, prevY: 90 };
  const destroyed = brickHit(ball, [brick]);
  assert.equal(destroyed.length, 1);
  assert.equal(ball.vx, -300, 'vx should flip');
  assert.equal(ball.vy, -300, 'vy should flip');
});

// Push out: after the bounce the ball no longer overlaps the brick.
test('brickHit: ball is pushed clear of the brick it hit', () => {
  const brick = brickFixture();
  const ball = { x: 320, y: 120, r: 7, vx: 0, vy: -300, prevX: 320, prevY: 200 };
  brickHit(ball, [brick]);
  assert.ok(
    collides({ ...ball, x: ball.x, y: ball.y }, { ...brick, alive: true }) === false,
    'ball should be outside the brick after the bounce'
  );
  assert.ok(ball.y >= brick.y + brick.h + ball.r, 'ball sits just below the brick');
});

// Neighbours: a seam overlapping two bricks emits exactly ONE bounce.
test('brickHit: seam between two bricks bounces once (no cancelling flips)', () => {
  const a = { x: 100, y: 100, w: 72, h: 20, row: 0, points: 10, alive: true };
  const b = { x: 180, y: 100, w: 72, h: 20, row: 0, points: 10, alive: true };
  const ball = { x: 176, y: 115, r: 7, vx: 0, vy: -400, prevX: 176, prevY: 200 };
  const destroyed = brickHit(ball, [a, b]);
  assert.equal(destroyed.length, 2, 'both seam bricks are destroyed');
  assert.ok(ball.vy > 0, 'vy flips exactly once (going up must come back down)');
  assert.equal(ball.vx, 0, 'a straight vertical shot keeps vx unchanged');
});

// Tunnelling: a fast ball that jumps over a brick between two frames is still
// caught, because the path is swept.
test('brickHit: fast ball cannot tunnel through a brick', () => {
  const brick = brickFixture();
  const ball = { x: 400, y: 110, r: 7, vx: 300, vy: 0, prevX: 200, prevY: 110 };
  const destroyed = brickHit(ball, [brick]);
  assert.equal(destroyed.length, 1, 'brick is hit even though the ball jumped over it');
  assert.ok(ball.vx < 0, 'vx should flip (bounce back to the left)');
});

// Small local helper: place the ball below the field without importing the
// height (coverage intentionally light).
function belowField() {
  return 500;
}

